mapper.insert:
insert into biz_publish_request (
    project_type, project_id, project_name, status, apply_by, apply_user_id, apply_time
) values (
    #{projectType}, #{projectId}, #{projectName}, coalesce(#{status}, '0'),
    #{applyBy}, #{applyUserId}, now()
)

mapper.select:
select * from biz_publish_request

    and status = #{status}
    and project_type = #{projectType}
    and project_id = #{projectId}
    and apply_user_id = #{applyUserId}

order by request_id desc
